import React, { useEffect, useState } from 'react';

let result = null;

function App() {
  const [data, setData] = useState({
  });

  const [input, setInput] = useState('');

  const handleSend = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: input }),
      });
      result = await response.json();
      console.log('Fetched data:', result);
      setData(result);
      console.log('Data set:', data);
      setInput('');
    } catch (err) {
      console.error('Error sending message:', err);
    }
  };

  return (
    <div>
      <h1>{data.defender}</h1>
      <h2>Winner: {data.winner}</h2>
      <h3>Number of Times: {data.numberOfTimes}</h3>
      <h4>Victory Reason: {data.victoryReason}</h4>
      <h5>Emoji: {data.emoji}</h5>
      <input
        type="text"
        value={input}
        onChange={e => setInput(e.target.value)}
        placeholder="Type your challenger's name"
      />
      <button onClick={handleSend}>Battle!</button>
    </div>
  );
}

export default App;
